  2123   *
  2124   * Since: 2.26
  2125   **/
  2126  void
  2127  g_date_time_get_ymd (GDateTime *datetime,
  2128                       gint      *year,
  2129                       gint      *month,
  2130                       gint      *day)
  2131  {
  2132    gint the_year;
  2133    gint the_month;
  2134    gint the_day;
  2135    gint remaining_days;
  2136    gint y100_cycles;
  2137    gint y4_cycles;
  2138    gint y1_cycles;
  2139    gint preceding;
  2140    gboolean leap;
