  2142    g_return_if_fail (datetime != NULL);
  2143
  2144    remaining_days = datetime->days;
  2145
  2146    /*
  2147     * We need to convert an offset in days to its year/month/day representation.
  2148     * Leap years makes this a little trickier than it should be, so we use
  2149     * 400, 100 and 4 years cycles here to get to the correct year.
  2150     */
  2151
  2152    /* Our days offset starts sets 0001-01-01 as day 1, if it was day 0 our
  2153     * math would be simpler, so let's do it */
  2154    remaining_days--;
