  2197    remaining_days -= preceding;
  2198    g_assert(0 <= remaining_days);
  2199
  2200    the_day = remaining_days + 1;
  2201
  2202  end:
  2203    if (year)
  2204      *year = the_year;
  2205    if (month)
  2206      *month = the_month;
  2207    if (day)
  2208      *day = the_day;
